import { createNotebook, addNode, getNode, validateNotebook } from './model.mjs';
import { initializeBoard, createFrame, syncFrameMembership } from './board-model.mjs';

// 本人の課題と判断を再構成したデモ。比較用に補った別案はメモに明記し、当時の発言・操作履歴とは区別する。
export function createIdeaStory() {
  const notebook = createNotebook(
    '思考の芽が生まれるまで',
    'AIが一気に案を完成させると、自分はその途中で何も選んでいない。細部を理解できず、後から調整するたびに方針がぶれる。その体験から「自分で考え、選んだ過程を残す道具」がほしくなった。本人の会話と課題をもとに再構成したデモです。比較用に補った別案は各メモに明記し、当時の発言や操作履歴そのものとは区別しています。',
  );
  const steps = [notebook.rootId];
  const groups = [
    [
      'AIの完成案が、自分の案になっていない',
      '最近はAIに聞くとアイデアが一気に完成する。でも途中の細かな選択を自分がしていない。そのまま作り始めてよいのか、という本人の違和感が出発点。',
      '#537b64',
      [
        [
          '途中を飛ばすと、熱意を持ちにくい',
          '自分が考えて選んだ実感がないため、作り手として細部まで取り組む気持ちが育ちにくいと感じた。AI一般についての実証的主張ではなく、本人が感じた課題。',
          'growing',
        ],
        [
          '細部の理由を、自分が説明できない',
          '後から調整する時、「それはどう決めたんだっけ」と何度も分からなくなる。完成した答えだけでは、選択の理由が手元に残らない。',
          'growing',
        ],
        [
          '土台が曖昧だと、次の判断がぶれる',
          'スタートで形が決まらないままAIに任せ、修正のたびに方向が揺れる。この状態を少しでも減らしたい。',
          'growing',
        ],
      ],
    ],
    [
      '速い答えより、自分が選ぶ過程を残す',
      'AIを使わないという話ではない。抽象的な考えから二つ、三つの可能性を出して、自分の判断を挟みながら具体化したい。',
      '#aa8142',
      [
        [
          'AIに最初から最後まで設計してもらう',
          '比較のために補った別案。速く完成案は得られるが、今回解きたい「自分が途中を理解していない」という課題が残るため、中心の体験にはしない。',
          'rejected',
        ],
        [
          '結論と、選ばなかった理由も残す',
          '選んだ先をさらに深め、保留・見送りも消さずに残す。後の変更で迷ったら、何を大事にしたかに戻れる土台にする。',
          'adopted',
        ],
        [
          '最初にすべての細部を確定する',
          '比較のために補った別案。細かく考えることは必要でも、最初にすべてを固定すると試して変えにくい。未決定を残しながら深める方を選ぶ。',
          'parked',
        ],
      ],
    ],
    [
      'AIを使っても、自分で考える',
      'AIに任せたい時も、一人で脳を使って考えたい時もある。どちらも使える道具にしたい。',
      '#597ea8',
      [
        [
          'AIは補足や問い返しをする',
          'ツリーを見て気づいた点を突っ込んでもらい、別の見方を得たい。',
          'adopted',
        ],
        [
          '承認してから枝に追加する',
          'AIが出した案をそのまま確定させず、自分が選んでツリーに入れる。',
          'adopted',
        ],
        [
          'AIを使わない時間も成立させる',
          'AIの呼び出しを前提にせず、手だけで考えを書き進められるようにする。',
          'adopted',
        ],
      ],
    ],
    [
      '考えが広がる見た目にしたい',
      '縦に並ぶノートより、フリーボードとして視覚的に広がるイメージだった。',
      '#8d68a2',
      [
        [
          '縦リストだけを主画面にする',
          '親子関係は表現できるが、想像していた自由空間とは違った。読むための副表示として残す。',
          'rejected',
        ],
        [
          'スマホはカードをダブルタップ',
          '同じ親から繰り返せば別案、子から繰り返せばさらに深い考えになる。',
          'adopted',
        ],
        [
          'PCはカードの端から分岐する',
          'ダブルタップはスマホの話。PCでは四角いカードの端から枝を出す。',
          'adopted',
        ],
      ],
    ],
    [
      '広げた考えを、自分の分類で整理',
      '線の色と大きな四角い枠を使って、枝も含めて考えをまとめたい。',
      '#aa6756',
      [
        [
          '線に好きな色を付ける',
          '採用・保留の判断と、色による自分なりの分類は別に扱う。',
          'adopted',
        ],
        [
          '名前付きの枠で囲む',
          '枠を動かすと中身も移動する。囲み直しても親子関係は変えない。',
          'adopted',
        ],
        [
          '画面の大部分をノートにする',
          '上下や横の固定メニューを減らし、自由に考える空間を主役にする。',
          'adopted',
        ],
      ],
    ],
    [
      'まず、ひとりで使い切れる形にする',
      '使うたびのAPI費用や接続設定を、考え始めるための必須条件にはしたくない。使い慣れたCodexと相談しながら試したい。',
      '#698387',
      [
        [
          '手動でAIに渡す経路を残す',
          '必要な範囲だけ依頼文としてコピーし、回答を承認して取り込む。AIを呼ばなくてもノート単体で使える。',
          'adopted',
        ],
        [
          'MCP接続・一般ノートのクラウド共有',
          'MCPを一度体験したい気持ちと、3枠まで共有したい希望はある。今回の期限では必須にせず、一般ノート共有は未対応と明示する。',
          'parked',
        ],
        [
          'この発想の流れを、体験できるデモに',
          '審査員にも枝をたどって、課題・選択・理由を実際のノートで読んでもらう。デモは閲覧専用で、自分のノートにコピーすれば自由に変えられる。',
          'adopted',
        ],
      ],
    ],
  ];
  getNode(notebook, notebook.rootId).position = { x: 0, y: 520 };
  groups.forEach(([title, note, color, ideas], index) => {
    const head = addNode(notebook, notebook.rootId, title, note);
    steps.push(head.id);
    head.position = { x: 340, y: index * 500 };
    head.lineColor = color;
    head.state = 'adopted';
    const memberIds = [head.id];
    ideas.forEach(([text, reason, state], offset) => {
      const child = addNode(notebook, head.id, text, reason);
      child.state = state;
      child.position = { x: 650, y: index * 500 + (offset - 1) * 140 };
      child.lineColor = color;
      memberIds.push(child.id);
    });
    createFrame(notebook, memberIds, `${index + 1}. ${title}`, color);
  });
  initializeBoard(notebook);
  syncFrameMembership(notebook);
  validateNotebook(notebook);
  return { notebook, steps };
}
